/* gx_system_pen_configure with GUIX 5.4.0 compatibility.

   In GUIX 5.4.0 and earlier the minimum drag distance was given as an integer
   shifted left by 8; it is now a GX_FIXED_VAL, shifted by GX_FIXED_VAL_SHIFT
   (10). Built for 5.4.0 compatibility, gx_system_pen_configure takes the old
   form and stores the same distance in the new one. The GUIX documentation's
   example: half a pixel per tick, (1 << 8) / 2 in 5.4.0, is
   GX_FIXED_VAL_MAKE(1) / 2 now. The maximum pen speed is stored as given. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_system.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_system_pen_configure_5_4_0_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

static UINT      failed_tests = 0;

static TX_THREAD test_thread;
static ULONG     test_thread_stack[8192 / sizeof(ULONG)];

static VOID test_thread_entry(ULONG id)
{
GX_PEN_CONFIGURATION configuration;

    gx_system_initialize();

    configuration.gx_pen_configuration_min_drag_dist = (1 << 8) / 2;
    configuration.gx_pen_configuration_max_pen_speed_ticks = 7;
    EXPECT_EQ(GX_SUCCESS, gx_system_pen_configure(&configuration));
    EXPECT_EQ(GX_FIXED_VAL_MAKE(1) / 2, _gx_system_pen_configuration.gx_pen_configuration_min_drag_dist);
    EXPECT_EQ(7, _gx_system_pen_configuration.gx_pen_configuration_max_pen_speed_ticks);

    configuration.gx_pen_configuration_min_drag_dist = 3 << 8;
    configuration.gx_pen_configuration_max_pen_speed_ticks = 12;
    EXPECT_EQ(GX_SUCCESS, gx_system_pen_configure(&configuration));
    EXPECT_EQ(GX_FIXED_VAL_MAKE(3), _gx_system_pen_configuration.gx_pen_configuration_min_drag_dist);
    EXPECT_EQ(12, _gx_system_pen_configuration.gx_pen_configuration_max_pen_speed_ticks);

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}

VOID tx_application_define(void *first_unused_memory)
{
    tx_thread_create(&test_thread, "test_thread", test_thread_entry, 0,
                     test_thread_stack, sizeof(test_thread_stack),
                     1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);
}

